import React, { useCallback } from 'react';
import { useIntl } from 'react-intl';
import type {
  ActionType,
  Column,
  ColumnInstance,
  Hooks,
  MetaBase,
  ReducerTableState,
  Row,
  TableInstance,
  TableState,
} from 'react-table';
import {
  actions,
  ensurePluginOrder,
  useMountedLayoutEffect,
  useGetLatest,
} from 'react-table';
import styled from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { MinusIcon, PlusIcon } from '@dynatrace/strato-icons';

import { SubRowsCell } from './SubRowsCell.js';
import { Button } from '../../../buttons/button/Button.js';
import {
  DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
} from '../../DataTable/constants.js';
import type {
  TableColumn,
  DataTableSubRowsHeaderProps,
} from '../../types/shared-table-types.js';
import { _convertColumn } from '../../types/table-type-mappings.js';
import { insertColumn } from '../../utils/column-utils.js';

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/ban-types*/

/** Actions provided by the plugin to trigger state updates */
export const useSubRowsActions = {
  /** Action for setting `openSubRows`. */
  resetSubRows: 'strato-reset-sub-rows',
  /** Action definition for updating the open sub rows. */
  updateOpenSubRows: 'strato-update-open-sub-rows',
};

const AllSubRowsTrigger = /* @__PURE__ */ styled(Button)<{
  $subRowsDepth: number;
}>(({ $subRowsDepth }) => ({
  borderRadius: Borders.Radius.Field.Subdued,
  padding: `0 ${Spacings.Size2}`,
  marginRight: `calc(${Spacings.Size16} * ${$subRowsDepth})`,
  display: 'flex',
}));

// Actions
actions.resetSubRows = useSubRowsActions.resetSubRows;
actions.updateOpenSubRows = useSubRowsActions.updateOpenSubRows;

export const TABLE_SUB_ROWS_DEFAULT_COLUMN = {
  id: 'strato-table-sub-rows-all-trigger',
  subRowsAccessor: 'subRows',
  disableSubRows: () => false,
  header: ({
    updateOpenSubRows,
    allSubRowsOpen,
    subRowsDepth,
  }: DataTableSubRowsHeaderProps) => {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    const intl = useIntl();
    return (
      <AllSubRowsTrigger
        onClick={() => updateOpenSubRows(!allSubRowsOpen)}
        $subRowsDepth={subRowsDepth}
        aria-label={
          allSubRowsOpen
            ? intl.formatMessage({
                defaultMessage: 'Close all sub rows',
                id: 'w0Cn6FIqio7R6kNp',
                description:
                  "Aria label used for the table's sub row close all trigger.",
              })
            : intl.formatMessage({
                defaultMessage: 'Open all sub rows',
                id: 'WzzE0B9V2fV9+Yqq',
                description:
                  "Aria label used for the table's sub row open all trigger.",
              })
        }
      >
        <Button.Prefix>
          {allSubRowsOpen ? <MinusIcon /> : <PlusIcon />}
        </Button.Prefix>
      </AllSubRowsTrigger>
    );
  },
  width: 0,
  cell: SubRowsCell,
};

const INTERNAL_TABLE_SUB_ROWS_DEFAULT_COLUMN = _convertColumn(
  TABLE_SUB_ROWS_DEFAULT_COLUMN,
);

/**
 * ColumnDeps additional hook. Defines when the memoed columns should be updated.
 * Adds a dependency to be updated when disableSubRows changes.
 */
function columnsDeps(deps: any[], { instance }: MetaBase<any>) {
  return [...deps, instance.disableSubRows];
}

/**
 * Additional Columns hook, will add a default expander column to the memoed
 * column definition automatically.
 */
function additionalColumn(columns: Column<any>[], { instance }: MetaBase<any>) {
  if (instance.disableSubRows) {
    return columns;
  }

  return insertColumn(columns, INTERNAL_TABLE_SUB_ROWS_DEFAULT_COLUMN, [
    DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
    DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  ]) as Column<any>[];
}

// Reducer
function reducer(
  state: TableState<any>,
  action: ActionType,
  previousState: TableState<any> | undefined,
  instance: TableInstance<any> | undefined,
): ReducerTableState<any> | undefined {
  if (action.type === actions.resetSubRows) {
    return {
      ...state,
      openSubRows: (instance?.initialState as TableState).openSubRows || {},
    };
  }

  if (action.type === actions.updateOpenSubRows) {
    const { payload: updatedOpenSubRows } = action;

    return {
      ...state,
      openSubRows: updatedOpenSubRows,
    };
  }
}

function useInstance(instance: TableInstance<any>) {
  const {
    data,
    dispatch,
    autoResetSubRows = true,
    rows,
    rowsById,
    plugins,
    state: { openSubRows },
    columns,
    setOpenSubRows,
  } = instance;

  ensurePluginOrder(
    plugins,
    ['useSortBy', 'useGroupBy', 'usePivotColumns', 'useGlobalFilter'],
    'useSubRows',
  );

  const allSubRowsOpen = Object.entries(rowsById).every(([id, row]) => {
    return (
      !row.hasSubRows ||
      (row.hasSubRows && openSubRows[id]) ||
      row.subRowsDisabled
    );
  });

  const [rowsWithSubRows, rowsByIdWithSubRowsProps] = React.useMemo(() => {
    return getRowsWithSubRows(rows, openSubRows, columns);
  }, [rows, openSubRows, columns]);

  const subRowsDepth = React.useMemo(
    () => findSubRowsDepth(openSubRows),
    [openSubRows],
  );

  const getInstance = useGetLatest(instance);

  const getAutoResetSubRows = useGetLatest(autoResetSubRows);
  // Bypass any effects from firing when this changes
  useMountedLayoutEffect(() => {
    if (getAutoResetSubRows()) {
      dispatch({ type: actions.resetSubRows });
    }
  }, [dispatch, data]);

  /**
   * Updates the open sub rows. If a parent row is closed, all nested sub rows are closed and deselected as well.
   *
   * @param update - either the row id a boolean if all sub rows should be opened/closed
   */
  const updateOpenSubRows = useCallback(
    (update: string | boolean) => {
      let newOpenSubRows: Record<string, boolean> = {};
      if (typeof update === 'boolean') {
        if (update) {
          Object.entries(getInstance().rowsById).forEach(([rowId, row]) => {
            if (!row.subRowsDisabled && row.hasSubRows) {
              newOpenSubRows[rowId] = true;
            }
          });
        }
      } else {
        newOpenSubRows = {
          ...openSubRows,
        };
        if (newOpenSubRows[update]) {
          Object.keys(newOpenSubRows).forEach((key) => {
            if (key.startsWith(update)) {
              delete newOpenSubRows[key];
            }
          });
        } else {
          newOpenSubRows[update] = true;
        }
      }
      setOpenSubRows(newOpenSubRows);
    },
    [getInstance, openSubRows, setOpenSubRows],
  );

  Object.assign(instance, {
    rowsById: rowsByIdWithSubRowsProps,
    rowsWithoutSubRows: rows,
    rowsWithSubRows,
    rows: rowsWithSubRows,
    subRowsDepth,
    allSubRowsOpen,
    updateOpenSubRows,
  });
}

function findSubRowsDepth(openSubRows: Record<string, boolean>) {
  let maxDepth = 0;

  Object.keys(openSubRows).forEach((id) => {
    const splitId = id.split('.');
    maxDepth = Math.max(maxDepth, splitId.length);
  });

  return maxDepth;
}

/**
 * Iterates over all rows & subrows to get all currently open rows and update their sub rows props
 *
 * @param rows - current rows
 * @param openSubRows - open sub rows object
 * @returns current rows as well as all rows by id including additional sub rows props
 */
function getRowsWithSubRows(
  rows: Row[],
  openSubRows: Record<string, boolean>,
  columns: ColumnInstance<any>[],
) {
  const rowsWithSubRows: Row[] = [];
  const rowsByIdWithProps: Record<string, Row> = {};

  const handleRow = (
    row: Row,
    parentOpen: boolean = false,
    parentDisabled: boolean = false,
  ) => {
    row.hasSubRows = row.subRows && !!row.subRows.length;
    row.subRowsDisabled = parentDisabled || rowDisableSubRowsFn(row, columns);
    row.subRowsOpen = openSubRows[row.id] || false;
    parentOpen && rowsWithSubRows.push(row);
    rowsByIdWithProps[row.id] = row;

    if (row.hasSubRows) {
      row.subRows.forEach((subRow) =>
        handleRow(subRow, row.subRowsOpen, row.subRowsDisabled),
      );
    }
  };

  rows.forEach((row) => {
    handleRow(row, true, false);
  });

  return [rowsWithSubRows, rowsByIdWithProps];
}

/**
 * Checks if there is a custom function for disabling sub rows is defined and applies either that or the default one.
 *
 * @param row - the table row in question
 * @param columns - the table columns
 * @returns whether sub rows are disabled for the respective row
 */
const rowDisableSubRowsFn = (row: Row, columns: ColumnInstance<any>[]) => {
  const col = columns.find(
    (column) => column.id === TABLE_SUB_ROWS_DEFAULT_COLUMN.id,
  );
  if (col && col.disableSubRows) {
    return col.disableSubRows(row);
  } else {
    return TABLE_SUB_ROWS_DEFAULT_COLUMN.disableSubRows();
  }
};

/**
 * Checks if there is a custom accessor defined or uses the default one.
 * For string accessors a suitable accessor function is created and returned.
 *
 * @param originalColumns - original columns passed to the table
 * @returns sub rows accessor function
 */
export const getSubRowsAccessorFn = (originalColumns: TableColumn[]) => {
  const subRowsAccessor =
    originalColumns.find((col) => col.id === TABLE_SUB_ROWS_DEFAULT_COLUMN.id)
      ?.subRowsAccessor || TABLE_SUB_ROWS_DEFAULT_COLUMN.subRowsAccessor;

  if (typeof subRowsAccessor === 'string') {
    return (row: Row, index: number) =>
      subRowsAccessor.split('.').reduce((obj, key) => obj[key] || [], row);
  } else {
    return subRowsAccessor;
  }
};

/** Table hook that enables subRows on tables */
export function useSubRows<D extends Record<string, unknown>>(
  hooks: Hooks<D>,
): void {
  hooks.columns.push(additionalColumn);
  hooks.stateReducers.push(reducer);
  hooks.useInstance.push(useInstance);
  hooks.columnsDeps.push(columnsDeps);
}

useSubRows.pluginName = 'useSubRows';
